 motion.finished.then(()=>{if(preciseCardScene!==scene)return;to.style.opacity='';node.remove();snapshot?.remove();preciseCardScene=null;delete document.documentElement.dataset.gesture;restoreOperationsNav()}).catch(()=>{});
